# ---------------------------------------------------------------------------
# Pattern matching


def mask_comments_and_strings(text: str) -> str:
    """Return a same-length string with comments/strings blanked, preserving newlines."""
    out = list(text)
    i = 0
    n = len(text)
    state: Optional[str] = None
    triple: Optional[str] = None
    while i < n:
        ch = text[i]
        if state is None:
            if text.startswith("//", i):
                j = i
                while j < n and text[j] != "\n":
                    out[j] = " "; j += 1
                i = j; continue
            if text.startswith("/*", i):
                j = i
                while j < n and not text.startswith("*/", j):
                    if text[j] != "\n": out[j] = " "
                    j += 1
                for k in range(j, min(n, j + 2)):
                    if text[k] != "\n": out[k] = " "
                i = min(n, j + 2); continue
            if ch == "#":
                # Useful for Python/YAML/Ruby; harmless for most code snippets.
                j = i
                while j < n and text[j] != "\n":
                    out[j] = " "; j += 1
                i = j; continue
            if text.startswith("'''", i) or text.startswith('"""', i):
                triple = text[i:i+3]
                for k in range(i, min(n, i + 3)):
                    out[k] = " "
                i += 3; state = "triple"; continue
            if ch in ('"', "'", "`"):
                quote = ch
                out[i] = " "
                i += 1; state = quote; continue
            i += 1; continue
        if state == "triple":
            if triple and text.startswith(triple, i):
                for k in range(i, min(n, i + 3)):
                    if text[k] != "\n": out[k] = " "
                i += 3; state = None; triple = None
            else:
                if text[i] != "\n": out[i] = " "
                i += 1
            continue
        # quoted string/template
        quote = state
        if ch == "\\":
            if ch != "\n": out[i] = " "
            if i + 1 < n and text[i + 1] != "\n": out[i + 1] = " "
            i += 2; continue
        if ch == quote:
            out[i] = " "; i += 1; state = None; continue
        if ch != "\n": out[i] = " "
        i += 1
    return "".join(out)


def tokenize_pattern(pattern: str) -> List[Tuple[str, str]]:
    toks: List[Tuple[str, str]] = []
    i = 0
    while i < len(pattern):
        ch = pattern[i]
        if ch.isspace():
            j = i + 1
            while j < len(pattern) and pattern[j].isspace():
                j += 1
            toks.append(("ws", pattern[i:j])); i = j; continue
        if ch == "$":
            if pattern.startswith("$$$", i):
                j = i + 3
                while j < len(pattern) and (pattern[j].isalnum() or pattern[j] == "_"):
                    j += 1
                if j > i + 3:
                    toks.append(("multi", pattern[i+3:j])); i = j; continue
            j = i + 1
            while j < len(pattern) and (pattern[j].isalnum() or pattern[j] == "_"):
                j += 1
            if j > i + 1:
                toks.append(("meta", pattern[i+1:j])); i = j; continue
        # group literals into identifier/number or punctuation runs
        if ch.isalnum() or ch == "_":
            j = i + 1
            while j < len(pattern) and (pattern[j].isalnum() or pattern[j] in "_$"):
                j += 1
            toks.append(("lit", pattern[i:j])); i = j; continue
        # two-char operators
        if i + 1 < len(pattern) and pattern[i:i+2] in ("&&", "||", "==", "!=", "<=", ">=", "=>", "?.", "++", "--", "::"):
            toks.append(("lit", pattern[i:i+2])); i += 2; continue
        toks.append(("lit", ch)); i += 1
    return toks


def _literal_regex(lit: str, prev_typ: Optional[str], next_typ: Optional[str]) -> str:
    esc = re.escape(lit)
    if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_$]*", lit):
        # Keep keywords/identifiers from matching inside longer names.
        return rf"(?<![A-Za-z0-9_$]){esc}(?![A-Za-z0-9_$])"
    return esc


def _single_meta_regex(name: str, next_lit: Optional[str], at_end: bool) -> str:
    # Heuristic: when the metavariable ends a statement, capture an expression
    # up to newline/semicolon/brace. Otherwise capture the smallest expression
    # before the next delimiter.
    if at_end or next_lit in (None, ";", "}"):
        return rf"(?P<{name}>[^;\n}}]+?)"
    if next_lit == "(":
        return rf"(?P<{name}>[A-Za-z_$][A-Za-z0-9_$]*(?:\.[A-Za-z_$][A-Za-z0-9_$]*)*)"
    if next_lit in (",", ")", "]"):
        return rf"(?P<{name}>[^,\)\]\n;]+?)"
    if next_lit in ("&&", "||", "+", "-", "*", "/", "%", "==", "!=", "<=", ">=", "<", ">"):
        return rf"(?P<{name}>[^\n;]+?)"
    return rf"(?P<{name}>[^\n;]+?)"


def compile_pattern(pattern: str) -> Tuple[re.Pattern[str], List[str], List[str]]:
    toks = tokenize_pattern(pattern.strip())
    parts: List[str] = []
    seen: set[str] = set()
    multi_seen: set[str] = set()
    single_names: List[str] = []
    multi_names: List[str] = []
    for idx, (typ, val) in enumerate(toks):
        if typ == "ws":
            # In source code, AST matching ignores most whitespace. Requiring at
            # least one space between two word-like tokens avoids the worst
            # false positives while still allowing `code=bar`.
            prev = toks[idx - 1] if idx else (None, "")
            nxt = toks[idx + 1] if idx + 1 < len(toks) else (None, "")
            if prev[0] in ("lit", "meta", "multi") and nxt[0] in ("lit", "meta", "multi") and re.fullmatch(r"[A-Za-z0-9_$]+", prev[1]) and re.fullmatch(r"[A-Za-z0-9_$]+", nxt[1]):
                parts.append(r"\s+")
            else:
                parts.append(r"\s*")
        elif typ == "lit":
            prev = toks[idx - 1][0] if idx else None
            nxt = toks[idx + 1][0] if idx + 1 < len(toks) else None
            parts.append(_literal_regex(val, prev, nxt))
        elif typ == "meta":
            if val in seen:
                parts.append(rf"(?P={val})")
            else:
                # find next literal token
                next_lit = None
                for t2, v2 in toks[idx+1:]:
                    if t2 == "lit":
                        next_lit = v2; break
                    if t2 in ("meta", "multi"):
                        break
                at_end = not any(t != "ws" for t, _ in toks[idx+1:])
                parts.append(_single_meta_regex(val, next_lit, at_end))
                seen.add(val); single_names.append(val)
        elif typ == "multi":
            if val in multi_seen:
                parts.append(rf"(?P={val})")
            else:
                parts.append(rf"(?P<{val}>[\s\S]*?)")
                multi_seen.add(val); multi_names.append(val)
    regex = "".join(parts)
    # Tree-sitter patterns for declaration/return statements commonly include
    # the terminating semicolon in the reported match even when omitted from the
    # query. Add an optional semicolon for those statement-like patterns.
    stripped = pattern.strip()
    if not stripped.endswith(";") and re.match(r"^(var|let|const|return)\b", stripped):
        regex += r";?"
    try:
        return re.compile(regex, re.DOTALL), single_names, multi_names
    except re.error:
        # Literal fallback for pathological user input.
        return re.compile(re.escape(pattern), re.DOTALL), [], []


def split_multi_capture(val: str, base_start: int) -> List[Tuple[str, int, int]]:
    if val == "":
        return []
    # Split comma-separated arguments while preserving commas as observed in JSON.
    pieces: List[Tuple[str, int, int]] = []
    cur_start = 0
    for m in re.finditer(r",", val):
        before = val[cur_start:m.start()]
        if before.strip():
            off = len(before) - len(before.lstrip())
            endtrim = len(before.rstrip())
            pieces.append((before.strip(), base_start + cur_start + off, base_start + cur_start + endtrim))
        pieces.append((",", base_start + m.start(), base_start + m.end()))
        cur_start = m.end()
    tail = val[cur_start:]
    if tail.strip():
        off = len(tail) - len(tail.lstrip())
        endtrim = len(tail.rstrip())
        pieces.append((tail.strip(), base_start + cur_start + off, base_start + cur_start + endtrim))
    if not pieces and val.strip():
        off = len(val) - len(val.lstrip())
        pieces.append((val.strip(), base_start + off, base_start + len(val.rstrip())))
    return pieces


def search_pattern(source: FileSource, pattern: str, selector: Optional[str] = None) -> List[Match]:
    if pattern is None:
        return []
    pattern = str(pattern)
    rx, singles, multis = compile_pattern(pattern)
    # Use a masked copy for ordinary code patterns so simple identifiers do not
    # match comments/strings. Quoted patterns need the original text.
    hay = source.text if any(q in pattern for q in ('"', "'", "`")) else mask_comments_and_strings(source.text)
    matches: List[Match] = []
    for mm in rx.finditer(hay):
        s, e = mm.start(), mm.end()
        if e <= s:
            continue
        # Trim leading/trailing whitespace introduced by flexible matching, but
        # keep semicolons when they are part of the matched statement.
        while s < e and source.text[s].isspace():
            s += 1
        while e > s and source.text[e-1].isspace():
            e -= 1
        caps: Dict[str, Tuple[str, int, int]] = {}
        multi: Dict[str, List[Tuple[str, int, int]]] = {}
        ok = True
        for name in singles:
            try:
                cs, ce = mm.span(name)
            except IndexError:
                continue
            if cs < 0:
                continue
            # Trim captures.
            raw = source.text[cs:ce]
            lstrip = len(raw) - len(raw.lstrip())
            rstrip = len(raw.rstrip())
            cs2, ce2 = cs + lstrip, cs + rstrip
            val = source.text[cs2:ce2]
            if name in caps and caps[name][0] != val:
                ok = False; break
            caps[name] = (val, cs2, ce2)
        if not ok:
            continue
        for name in multis:
            try:
                cs, ce = mm.span(name)
            except IndexError:
                continue
            if cs >= 0:
                multi[name] = split_multi_capture(source.text[cs:ce], cs)
        # Avoid matching empty/comment-only snippets.
        if not source.text[s:e].strip():
            continue
        matches.append(Match(file=source.path, source=source, start=s, end=e, captures=caps, multi=multi))
    return matches


def search_kind(source: FileSource, kind: str, regex: Optional[str] = None) -> List[Match]:
    # Lightweight support for the frequently documented `kind: identifier`.
    kind_l = (kind or "").lower()
    if kind_l not in ("identifier", "property_identifier", "field_identifier", "variable_name"):
        return []
    mask = mask_comments_and_strings(source.text)
    out: List[Match] = []
    rr = re.compile(regex) if regex else None
    for mm in re.finditer(r"\b[A-Za-z_$][A-Za-z0-9_$]*\b", mask):
        val = source.text[mm.start():mm.end()]
        if val in JS_KEYWORDS:
            continue
        if rr and not rr.search(val):
            continue
        out.append(Match(file=source.path, source=source, start=mm.start(), end=mm.end()))
    return out


def apply_template(template: str, m: Match) -> str:
    def repl(mm: re.Match[str]) -> str:
        multi = mm.group(1)
        single = mm.group(2)
        if multi:
            vals = m.multi.get(multi)
            if vals:
                return " ".join(v for v, _, _ in vals)
            if multi in m.captures:
                return m.captures[multi][0]
            return ""
        if single:
            return m.captures.get(single, ("", 0, 0))[0]
        return mm.group(0)
    return re.sub(r"\$\$\$([A-Za-z_][A-Za-z0-9_]*)|\$([A-Za-z_][A-Za-z0-9_]*)", repl, template)


def collect_files(paths: List[str], lang: Optional[str], globs: List[str], follow: bool = False,
                  include_hidden: bool = False) -> Tuple[List[FileSource], int]:
    if not paths:
        paths = ["."]
    sources: List[FileSource] = []
    skipped = 0

    def glob_ok(path: Path) -> bool:
        if not globs:
            return True
        rel = rel_path(path)
        state: Optional[bool] = None
        for g in globs:
            neg = g.startswith("!")
            pat = g[1:] if neg else g
            if fnmatch.fnmatch(rel, pat) or fnmatch.fnmatch(path.name, pat):
                state = not neg
        return True if state is None else state

    def consider(path: Path) -> None:
        nonlocal skipped
        if not path.is_file():
            return
        if not include_hidden and any(part.startswith(".") for part in path.parts if part not in (".", "..")):
            skipped += 1; return
        f_lang = lang_for_path(str(path))
        if not f_lang:
            skipped += 1; return
        if lang and f_lang != lang:
            skipped += 1; return
        if not glob_ok(path):
            skipped += 1; return
        try:
            text = path.read_text(encoding="utf-8", errors="replace")
        except Exception:
            skipped += 1; return
        sources.append(FileSource(rel_path(path), text, f_lang))

    for p in paths:
        path = Path(p)
        if path.is_dir():
            for root, dirs, files in os.walk(path, followlinks=follow):
                dirs.sort(); files.sort()
                if not include_hidden:
                    dirs[:] = [d for d in dirs if not d.startswith(".") and d not in (".git", "node_modules", "target")]
                for fn in files:
                    if not include_hidden and fn.startswith("."):
                        skipped += 1; continue
                    consider(Path(root) / fn)
        else:
            consider(path)
    return sources, skipped


def apply_replacements(text: str, matches: List[Match]) -> str:
    reps = [m for m in matches if m.replacement is not None]
    reps.sort(key=lambda m: (m.replacement_start if m.replacement_start is not None else m.start), reverse=True)
    out = text
    last_start = len(text) + 1
    for m in reps:
        s = m.replacement_start if m.replacement_start is not None else m.start
        e = m.replacement_end if m.replacement_end is not None else m.end
        if e > last_start:
            continue
        out = out[:s] + (m.replacement or "") + out[e:]
        last_start = s
    return out


def render_diff(old: str, new: str, path: str) -> str:
    old_lines = old.splitlines()
    new_lines = new.splitlines()
    out = [path, f"@@ -0,{len(old_lines)} +0,{len(new_lines)} @@"]
    w = max(1, len(str(max(len(old_lines), len(new_lines), 1))))
    sm = SequenceMatcher(a=old_lines, b=new_lines)
    old_no = new_no = 1
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == "equal":
            for line in old_lines[i1:i2]:
                out.append(f"{old_no:>{w}} {new_no:>{w}}│ {line}")
                old_no += 1; new_no += 1
        elif tag == "delete":
            for line in old_lines[i1:i2]:
                out.append(f"{old_no:>{w}} {' ' * w}│-{line}")
