                old_no += 1
            for line in new_lines[j1:j2]:
                out.append(f"{' ' * w} {new_no:>{w}}│+{line}")
                new_no += 1
    return "\n".join(out)


def colorize_line(line: str, line_start: int, matches: List[Match]) -> str:
    spans: List[Tuple[int, int]] = []
    for m in matches:
        s = max(m.start - line_start, 0)
        e = min(m.end - line_start, len(line))
        if e > s:
            spans.append((s, e))
    if not spans:
        return line
    spans.sort()
