def find_config(config_arg: Optional[str] = None) -> Tuple[Optional[Path], Optional[Dict[str, Any]], Optional[int]]:
    if config_arg:
        p = Path(config_arg)
        if not p.exists():
            return None, None, read_config_error()
        try:
            data = parse_yaml_text(p.read_text(encoding="utf-8", errors="replace")) or {}
        except Exception as e:
            return None, None, read_config_error(str(e))
        return p.resolve(), data if isinstance(data, dict) else {}, None
    cur = Path.cwd().resolve()
