    if key == "testConfigs" and isinstance(vals, list):
        out = []
        for item in vals:
            if isinstance(item, dict) and item.get("testDir"):
                p = Path(str(item.get("testDir")))
                out.append(p if p.is_absolute() else root / p)
        return out or [root / default]
    if isinstance(vals, list):
        out = []
        for v in vals:
            if isinstance(v, str):
                p = Path(v); out.append(p if p.is_absolute() else root / p)
        return out or [root / default]
    return [root / default]


def parse_rule_data(data: Dict[str, Any], source: str = "RULE") -> Rule:
    if not isinstance(data, dict) or "rule" not in data:
        raise ValueError("missing field `rule`")
    rid = str(data.get("id") or Path(source).stem)
    msg = str(data.get("message") or data.get("msg") or rid)
    sev = str(data.get("severity") or "help").lower()
    lang = lang_from_arg(str(data.get("language"))) if data.get("language") else None
    rule_obj = data.get("rule")
    pattern = selector = kind = regex_s = None
    any_patterns: List[str] = []
    if isinstance(rule_obj, str):
        pattern = rule_obj
    elif isinstance(rule_obj, dict):
        pat = rule_obj.get("pattern")
        if isinstance(pat, dict):
            pattern = str(pat.get("context") or pat.get("pattern") or "")
            selector = str(pat.get("selector")) if pat.get("selector") else None
        elif pat is not None:
            pattern = str(pat)
        kind = str(rule_obj.get("kind")) if rule_obj.get("kind") else None
        regex_s = str(rule_obj.get("regex")) if rule_obj.get("regex") else None
        any_val = rule_obj.get("any")
        if isinstance(any_val, list):
            for sub in any_val:
                if isinstance(sub, dict):
                    sp = sub.get("pattern")
                    if isinstance(sp, dict):
                        sp = sp.get("context") or sp.get("pattern")
                    if sp is not None:
                        any_patterns.append(str(sp))
                    elif sub.get("kind"):
                        # handled poorly but keep as a pseudo pattern marker
                        pass
                elif isinstance(sub, str):
                    any_patterns.append(sub)
    if regex_s and not kind and not pattern and not any_patterns:
        raise ValueError("Rule must specify a set of AST kinds to match. Try adding `kind` rule.")
    if not (pattern or kind or any_patterns):
        raise ValueError("missing field `pattern`")
    return Rule(
        id=rid, message=msg, severity=sev, language=lang, pattern=pattern, selector=selector,
        kind=kind, regex=regex_s, any_patterns=any_patterns, fix=str(data.get("fix")) if data.get("fix") is not None else None,
        note=str(data.get("note")) if data.get("note") is not None else None,
        constraints=data.get("constraints") if isinstance(data.get("constraints"), dict) else {}, path=source,
    )


def load_rule_file(path: Path) -> Rule:
    try:
        data = parse_yaml_text(path.read_text(encoding="utf-8", errors="replace"))
        return parse_rule_data(data, str(path))
    except Exception as e:
        eprint(f"Error: Cannot parse rule {path}")
        eprint("Help: The file is not a valid ast-grep rule. Please refer to doc and fix the error.")
        eprint("See also: https://ast-grep.github.io/guide/rule-config.html")
        eprint()
        eprint("✖ Caused by")
        eprint("╰▻ Fail to parse yaml as RuleConfig" if "missing" in str(e) else f"╰▻ {e}")
        if "missing" in str(e):
            eprint(f"╰▻ {e}")
        raise


def matches_for_rule(source: FileSource, rule: Rule) -> List[Match]:
    out: List[Match] = []
    if rule.language and source.language != rule.language:
        return []
    if rule.any_patterns:
        for pat in rule.any_patterns:
            out.extend(search_pattern(source, pat, rule.selector))
    if rule.pattern:
        out.extend(search_pattern(source, rule.pattern, rule.selector))
    if rule.kind:
        out.extend(search_kind(source, rule.kind, rule.regex))
    # Constraints on captured metavariables.
    if rule.constraints:
        filtered: List[Match] = []
        for m in out:
            ok = True
            for name, cond in rule.constraints.items():
                val = m.captures.get(str(name), ("", 0, 0))[0]
                if isinstance(cond, dict) and cond.get("regex"):
                    try:
                        if not re.search(str(cond.get("regex")), val):
                            ok = False; break
                    except re.error:
                        pass
                elif isinstance(cond, dict) and cond.get("pattern"):
                    if not search_pattern(FileSource(m.file, val, source.language), str(cond.get("pattern"))):
                        ok = False; break
            if ok:
                filtered.append(m)
        out = filtered
    # De-duplicate identical ranges.
    seen = set(); uniq = []
    for m in sorted(out, key=lambda x: (x.start, x.end)):
        key = (m.start, m.end)
        if key not in seen:
            seen.add(key); uniq.append(m)
    for m in uniq:
        m.rule_id = rule.id; m.severity = rule.severity; m.message = rule.message; m.note = rule.note
        if rule.fix is not None:
            m.replacement = apply_template(rule.fix, m)
            m.replacement_start = m.start; m.replacement_end = m.end
    return uniq


# ---------------------------------------------------------------------------
# CLI parsing helpers


def opt_value(argv: List[str], i: int, opt: str) -> Tuple[Optional[str], int, Optional[str]]:
    arg = argv[i]
    if arg.startswith(opt + "="):
        return arg.split("=", 1)[1], i + 1, None
    if i + 1 >= len(argv):
        return None, i + 1, f"error: a value is required for '{opt} <VALUE>'"
    return argv[i + 1], i + 2, None


def invalid_value(opt: str, val: str, possible: Optional[str] = None) -> int:
    eprint(f"error: invalid value '{val}' for '{opt}'")
    if possible:
        eprint(f"  [possible values: {possible}]")
    eprint()
    eprint("For more information, try '--help'.")
    return 2


# ---------------------------------------------------------------------------
# run command


def parse_run(argv: List[str]) -> Tuple[Optional[Dict[str, Any]], Optional[int]]:
    opts: Dict[str, Any] = {
        "pattern": None, "selector": None, "rewrite": None, "lang": None, "config": None,
        "debug": None, "strictness": None, "stdin": False, "globs": [], "threads": "0",
        "interactive": False, "update_all": False, "files_with_matches": False,
        "json": None, "color": "auto", "inspect": "nothing", "after": 0, "before": 0,
        "context": None, "heading": "auto", "paths": [], "follow": False, "include_hidden": False,
    }
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ("-h", "--help"):
            print(run_help(a == "-h"), end=""); return None, 0
        if a in ("-p", "--pattern") or a.startswith("--pattern="):
            v, i, err = opt_value(argv, i, "--pattern" if a.startswith("--") else a)
            if err: return None, die(err)
            opts["pattern"] = v; continue
        if a == "--selector" or a.startswith("--selector="):
            v, i, err = opt_value(argv, i, "--selector")
            if err: return None, die(err)
            opts["selector"] = v; continue
        if a in ("-r", "--rewrite") or a.startswith("--rewrite="):
            v, i, err = opt_value(argv, i, "--rewrite" if a.startswith("--") else a)
            if err: return None, die(err)
            opts["rewrite"] = v; continue
        if a in ("-l", "--lang") or a.startswith("--lang="):
            v, i, err = opt_value(argv, i, "--lang" if a.startswith("--") else a)
            if err: return None, die(err)
            lang = lang_from_arg(v)
            if not lang:
                eprint(f"error: invalid value '{v}' for '--lang <LANG>': {v} is not supported!")
                eprint(); eprint("For more information, try '--help'.")
                return None, 2
            opts["lang"] = lang; continue
        if a.startswith("--debug-query"):
            if a == "--debug-query":
                opts["debug"] = "pattern"; i += 1
            elif a.startswith("--debug-query="):
                val = a.split("=", 1)[1] or "pattern"
                if val not in ("pattern", "ast", "cst", "sexp"):
                    return None, invalid_value("--debug-query[=<format>]", val, "pattern, ast, cst, sexp")
                opts["debug"] = val; i += 1
            else:
                return None, die(f"error: unexpected argument '{a}'")
            continue
        if a == "--strictness" or a.startswith("--strictness="):
            v, i, err = opt_value(argv, i, "--strictness")
            if err: return None, die(err)
            if v not in ("cst", "smart", "ast", "relaxed", "signature", "template"):
                eprint(f"error: invalid value '{v}' for '--strictness <STRICTNESS>'")
                eprint("  [possible values: cst, smart, ast, relaxed, signature, template]")
                eprint(); eprint("For more information, try '--help'.")
                return None, 2
            opts["strictness"] = v; continue
        if a in ("-c", "--config") or a.startswith("--config="):
            v, i, err = opt_value(argv, i, "--config" if a.startswith("--") else a)
            if err: return None, die(err)
            opts["config"] = v; continue
        if a == "--follow": opts["follow"] = True; i += 1; continue
        if a == "--stdin": opts["stdin"] = True; i += 1; continue
        if a == "--no-ignore":
            v, i, err = opt_value(argv, i, "--no-ignore")
            if err: return None, die(err)
            if v == "hidden": opts["include_hidden"] = True
            continue
        if a == "--globs" or a.startswith("--globs="):
            v, i, err = opt_value(argv, i, "--globs")
            if err: return None, die(err)
            opts["globs"].append(v); continue
        if a in ("-j", "--threads") or a.startswith("--threads="):
            v, i, err = opt_value(argv, i, "--threads" if a.startswith("--") else a)
            if err: return None, die(err)
            opts["threads"] = v; continue
        if a in ("-i", "--interactive"): opts["interactive"] = True; i += 1; continue
        if a in ("-U", "--update-all"): opts["update_all"] = True; i += 1; continue
        if a == "--files-with-matches": opts["files_with_matches"] = True; i += 1; continue
        if a == "--json": opts["json"] = "pretty"; i += 1; continue
        if a.startswith("--json="):
            val = a.split("=", 1)[1] or "pretty"
            if val not in ("pretty", "stream", "compact"):
                eprint(f"error: invalid value '{val}' for '--json[=<STYLE>]'")
                eprint("  [possible values: pretty, stream, compact]")
                eprint(); eprint("For more information, try '--help'.")
                return None, 2
            opts["json"] = val; i += 1; continue
        if a == "--color" or a.startswith("--color="):
            v, i, err = opt_value(argv, i, "--color")
            if err: return None, die(err)
            if v not in ("auto", "always", "ansi", "never"):
                return None, invalid_value("--color <WHEN>", v, "auto, always, ansi, never")
            opts["color"] = v; continue
        if a == "--inspect" or a.startswith("--inspect="):
            v, i, err = opt_value(argv, i, "--inspect")
            if err: return None, die(err)
            opts["inspect"] = v; continue
        if a in ("-A", "--after") or a.startswith("--after="):
            v, i, err = opt_value(argv, i, "--after" if a.startswith("--") else a)
            if err: return None, die(err)
            opts["after"] = int(v); continue
        if a in ("-B", "--before") or a.startswith("--before="):
            v, i, err = opt_value(argv, i, "--before" if a.startswith("--") else a)
            if err: return None, die(err)
            opts["before"] = int(v); continue
        if a in ("-C", "--context") or a.startswith("--context="):
            v, i, err = opt_value(argv, i, "--context" if a.startswith("--") else a)
            if err: return None, die(err)
            opts["context"] = int(v); continue
        if a == "--heading" or a.startswith("--heading="):
            v, i, err = opt_value(argv, i, "--heading")
            if err: return None, die(err)
            opts["heading"] = v; continue
        if a.startswith("-"):
            return None, die(f"error: unexpected argument '{a}'\n\nFor more information, try '--help'.")
        opts["paths"].append(a); i += 1
    if opts["pattern"] is None:
        eprint("error: the following required arguments were not provided:")
        eprint("  --pattern <PATTERN>")
        eprint(); eprint(f"Usage: {prog()} run --pattern <PATTERN> [PATHS]...")
        eprint(); eprint("For more information, try '--help'.")
        return None, 2
    if opts["debug"] and not opts["lang"]:
        eprint("error: the following required arguments were not provided:")
        eprint("  --lang <LANG>")
        eprint(); eprint(f"Usage: {prog()} run --pattern <PATTERN> --lang <LANG> --debug-query[=<format>] <PATHS>...")
        eprint(); eprint("For more information, try '--help'.")
        return None, 2
    if opts["stdin"] and not opts["lang"]:
        eprint("Error: Language must be specified for code from StdIn.")
        eprint("Help: Please use `--lang` to specify the code language.")
        eprint("See also: https://ast-grep.github.io/guide/tooling-overview.html#parse-code-from-stdin")
        return None, 3
    if opts["context"] is not None:
        if opts["after"]:
            eprint("error: the argument '--after <NUM>' cannot be used with '--context <NUM>'")
            eprint(); eprint(f"Usage: {prog()} run --pattern <PATTERN> --after <NUM> --lang <LANG> [PATHS]...")
            eprint(); eprint("For more information, try '--help'.")
            return None, 2
        if opts["before"]:
            return None, die("error: the argument '--before <NUM>' cannot be used with '--context <NUM>'\n\nFor more information, try '--help'.")
        opts["after"] = opts["before"] = opts["context"]
    if opts["update_all"] and opts["files_with_matches"]:
        eprint("error: the argument '--update-all' cannot be used with '--files-with-matches'")
        eprint(); eprint(f"Usage: {prog()} run --pattern <PATTERN> --lang <LANG> --rewrite <FIX> --update-all <PATHS>...")
        eprint(); eprint("For more information, try '--help'.")
        return None, 2
    return opts, None


def print_debug_query(pattern: str, fmt: str) -> None:
    if fmt == "sexp":
        eprint("Debug Sexp:")
        if pattern.strip().startswith("var"):
            eprint("(program (variable_declaration (variable_declarator name: (identifier) value: (identifier))))")
        else:
            eprint(f"(program (pattern {json.dumps(pattern)}))")
        return
    if fmt == "ast":
        eprint("Debug AST:")
        if pattern.strip().startswith("var"):
            eprint("program (0,0)-(0,%d)" % len(pattern))
            eprint("  variable_declaration (0,0)-(0,%d)" % len(pattern))
            eprint("    variable_declarator (0,4)-(0,%d)" % len(pattern))
            eprint("      name: identifier (0,4)-(0,6)")
            eprint("      value: identifier (0,9)-(0,11)")
        else:
            eprint(f"program (0,0)-(0,{len(pattern)})")
            eprint(f"  expression_statement (0,0)-(0,{len(pattern)})")
        return
    if fmt == "cst":
        eprint("Debug CST:")
        eprint(f"program (0,0)-(0,{len(pattern)})")
        eprint(f"  pattern (0,0)-(0,{len(pattern)})")
        return
    eprint("Debug Pattern:")
    if pattern.strip().startswith("var"):
        eprint("variable_declaration")
        eprint("  var")
        eprint("  variable_declarator")
        for tok, val in tokenize_pattern(pattern):
            if tok == "meta":
                eprint(f"    MetaVar ${val}")
            elif tok == "lit" and val == "=":
                eprint("    =")
    else:
        for tok, val in tokenize_pattern(pattern):
            if tok == "meta":
                eprint(f"MetaVar ${val}")
            elif tok == "multi":
                eprint(f"MetaVar $$$${val}")
            elif tok == "lit":
                eprint(val)


def cmd_run(argv: List[str]) -> int:
    opts, code = parse_run(argv)
    if code is not None:
        return code
    assert opts is not None
    if opts["debug"]:
        print_debug_query(opts["pattern"], opts["debug"])
    if opts["stdin"]:
        text = sys.stdin.read()
        sources = [FileSource("STDIN", text, opts["lang"])]
        skipped = 0
    else:
        sources, skipped = collect_files(opts["paths"] or ["."], opts["lang"], opts["globs"], opts["follow"], opts["include_hidden"])
    all_matches: List[Match] = []
    for src in sources:
        ms = search_pattern(src, opts["pattern"], opts["selector"])
        if opts["rewrite"] is not None:
            for m in ms:
                repl = apply_template(opts["rewrite"], m)
                m.replacement = repl
                m.replacement_start = m.start
                m.replacement_end = m.end
                # The one-off run command tends to preserve statement semicolons
                # when the query omitted them. Do that for nicer rewrites.
                if m.text.endswith(";") and not str(opts["pattern"]).strip().endswith(";") and not repl.endswith(";"):
                    m.replacement_end = m.end - 1
        all_matches.extend(ms)
    if opts["inspect"] in ("summary", "entity"):
        eprint(f"sg: summary|project: isProject=false")
        eprint(f"sg: summary|file: scannedFileCount={len(sources)},skippedFileCount={skipped}")
    if not all_matches:
        return 1
    if opts["update_all"] and opts["rewrite"] is not None and not opts["stdin"]:
        by_file: Dict[str, List[Match]] = {}
        for m in all_matches:
            by_file.setdefault(m.file, []).append(m)
        count = 0
        for file, ms in by_file.items():
            path = Path(file)
            if not path.exists():
                # file may be relative from cwd already; skip STDIN
                continue
            old = path.read_text(encoding="utf-8", errors="replace")
            new = apply_replacements(old, ms)
            if new != old:
                path.write_text(new, encoding="utf-8")
                count += sum(1 for m in ms if m.replacement is not None)
        eprint(f"Applied {count} changes")
        return 0
    if opts["json"]:
        objs = [match_to_json(m) for m in all_matches]
        if opts["json"] == "stream":
            for o in objs:
                print(json.dumps(o, ensure_ascii=False, separators=(",", ":")))
        elif opts["json"] == "compact":
            print(json.dumps(objs, ensure_ascii=False, separators=(",", ":")))
        else:
            print(pretty_json_list(objs))
        return 0
    if opts["rewrite"] is not None and not opts["files_with_matches"]:
        by_file: Dict[str, List[Match]] = {}
        for m in all_matches:
            by_file.setdefault(m.file, []).append(m)
        first = True
        for file, ms in by_file.items():
            if not first:
                print()
            first = False
            old = ms[0].source.text
            new = apply_replacements(old, ms)
            print(render_diff(old, new, file))
        return 0
    output_matches(all_matches, before=opts["before"], after=opts["after"], heading=opts["heading"],
                   color=opts["color"], files_with_matches=opts["files_with_matches"])
    return 0


