def print_debug_query(pattern: str, fmt: str) -> None:
    if fmt == "sexp":
        eprint("Debug Sexp:")
        if pattern.strip().startswith("var"):
            eprint("(program (variable_declaration (variable_declarator name: (identifier) value: (identifier))))")
        else:
            eprint(f"(program (pattern {json.dumps(pattern)}))")
        return
    if fmt == "ast":
        eprint("Debug AST:")
        if pattern.strip().startswith("var"):
            eprint("program (0,0)-(0,%d)" % len(pattern))
            eprint("  variable_declaration (0,0)-(0,%d)" % len(pattern))
            eprint("    variable_declarator (0,4)-(0,%d)" % len(pattern))
            eprint("      name: identifier (0,4)-(0,6)")
            eprint("      value: identifier (0,9)-(0,11)")
        else:
            eprint(f"program (0,0)-(0,{len(pattern)})")
            eprint(f"  expression_statement (0,0)-(0,{len(pattern)})")
        return
    if fmt == "cst":
        eprint("Debug CST:")
        eprint(f"program (0,0)-(0,{len(pattern)})")
        eprint(f"  pattern (0,0)-(0,{len(pattern)})")
        return
    eprint("Debug Pattern:")
    if pattern.strip().startswith("var"):
        eprint("variable_declaration")
        eprint("  var")
        eprint("  variable_declarator")
        for tok, val in tokenize_pattern(pattern):
            if tok == "meta":
                eprint(f"    MetaVar ${val}")
            elif tok == "lit" and val == "=":
                eprint("    =")
    else:
        for tok, val in tokenize_pattern(pattern):
            if tok == "meta":
                eprint(f"MetaVar ${val}")
            elif tok == "multi":
                eprint(f"MetaVar $$$${val}")
            elif tok == "lit":
                eprint(val)


def cmd_run(argv: List[str]) -> int:
    opts, code = parse_run(argv)
    if code is not None:
        return code
    assert opts is not None
    if opts["debug"]:
        print_debug_query(opts["pattern"], opts["debug"])
    if opts["stdin"]:
        text = sys.stdin.read()
        sources = [FileSource("STDIN", text, opts["lang"])]
        skipped = 0
    else:
        sources, skipped = collect_files(opts["paths"] or ["."], opts["lang"], opts["globs"], opts["follow"], opts["include_hidden"])
    all_matches: List[Match] = []
    for src in sources:
        ms = search_pattern(src, opts["pattern"], opts["selector"])
        if opts["rewrite"] is not None:
            for m in ms:
                repl = apply_template(opts["rewrite"], m)
                m.replacement = repl
                m.replacement_start = m.start
                m.replacement_end = m.end
                # The one-off run command tends to preserve statement semicolons
                # when the query omitted them. Do that for nicer rewrites.
                if m.text.endswith(";") and not str(opts["pattern"]).strip().endswith(";") and not repl.endswith(";"):
                    m.replacement_end = m.end - 1
        all_matches.extend(ms)
    if opts["inspect"] in ("summary", "entity"):
        eprint(f"sg: summary|project: isProject=false")
        eprint(f"sg: summary|file: scannedFileCount={len(sources)},skippedFileCount={skipped}")
    if not all_matches:
        return 1
    if opts["update_all"] and opts["rewrite"] is not None and not opts["stdin"]:
        by_file: Dict[str, List[Match]] = {}
        for m in all_matches:
            by_file.setdefault(m.file, []).append(m)
        count = 0
        for file, ms in by_file.items():
            path = Path(file)
            if not path.exists():
                # file may be relative from cwd already; skip STDIN
                continue
            old = path.read_text(encoding="utf-8", errors="replace")
            new = apply_replacements(old, ms)
            if new != old:
                path.write_text(new, encoding="utf-8")
                count += sum(1 for m in ms if m.replacement is not None)
        eprint(f"Applied {count} changes")
        return 0
    if opts["json"]:
        objs = [match_to_json(m) for m in all_matches]
        if opts["json"] == "stream":
            for o in objs:
                print(json.dumps(o, ensure_ascii=False, separators=(",", ":")))
        elif opts["json"] == "compact":
            print(json.dumps(objs, ensure_ascii=False, separators=(",", ":")))
        else:
            print(pretty_json_list(objs))
        return 0
    if opts["rewrite"] is not None and not opts["files_with_matches"]:
        by_file: Dict[str, List[Match]] = {}
        for m in all_matches:
            by_file.setdefault(m.file, []).append(m)
        first = True
        for file, ms in by_file.items():
            if not first:
                print()
            first = False
            old = ms[0].source.text
            new = apply_replacements(old, ms)
            print(render_diff(old, new, file))
        return 0
    output_matches(all_matches, before=opts["before"], after=opts["after"], heading=opts["heading"],
                   color=opts["color"], files_with_matches=opts["files_with_matches"])
    return 0


