def create_project(name: Optional[str] = None) -> int:
    # Do not create inside an existing project.
    cur = Path.cwd().resolve()
    for d in [cur] + list(cur.parents):
        if (d / "sgconfig.yml").exists() or (d / "sgconfig.yaml").exists():
            eprint("Error: ast-grep project already exists.")
            eprint("Help: You are already inside a sub-folder of an ast-grep project. Try finding sgconfig.yml in ancestor directory?")
            eprint("See also: https://ast-grep.github.io/guide/scan-project.html")
            return 17
    root = cur / name if name else cur
    root.mkdir(parents=True, exist_ok=True)
    (root / "rules").mkdir(exist_ok=True)
    (root / "rule-tests").mkdir(exist_ok=True)
    (root / "utils").mkdir(exist_ok=True)
    for sub in ("rules", "rule-tests", "utils"):
        (root / sub / ".gitkeep").write_text("", encoding="utf-8")
    (root / "sgconfig.yml").write_text(
        f"ruleDirs:\n- {(root / 'rules').as_posix()}\n"
        f"testConfigs:\n- testDir: {(root / 'rule-tests').as_posix()}\n"
        f"utilDirs:\n- {(root / 'utils').as_posix()}\n",
        encoding="utf-8",
    )
    print("Your new ast-grep project has been created!")
    return 0


def parse_new(argv: List[str]) -> Tuple[Optional[Dict[str, Any]], Optional[int]]:
    opts = {"lang": None, "yes": False, "config": None, "positionals": []}
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ("-h", "--help"):
            print(new_help(a == "-h"), end=""); return None, 0
        if a in ("project", "rule", "test", "util") and i + 1 < len(argv) and argv[i+1] in ("-h", "--help"):
            print(new_help(argv[i+1] == "-h", a), end=""); return None, 0
        if a == "help":
            sub = argv[i+1] if i + 1 < len(argv) else None
            print(new_help(False, sub if sub in ("project", "rule", "test", "util") else None), end=""); return None, 0
        if a in ("-l", "--lang") or a.startswith("--lang="):
            v, i, err = opt_value(argv, i, "--lang" if a.startswith("--") else a)
            if err: return None, die(err)
            lang = lang_from_arg(v)
            if not lang:
                eprint(f"error: invalid value '{v}' for '--lang <LANG>': {v} is not supported!")
                eprint(); eprint("For more information, try '--help'.")
                return None, 2
            opts["lang"] = lang; continue
        if a in ("-y", "--yes"): opts["yes"] = True; i += 1; continue
        if a in ("-c", "--config") or a.startswith("--config="):
            v, i, err = opt_value(argv, i, "--config" if a.startswith("--") else a)
            if err: return None, die(err)
            opts["config"] = v; continue
        if a.startswith("-"):
            return None, die(f"error: unexpected argument '{a}'\n\nFor more information, try '--help'.")
        opts["positionals"].append(a); i += 1
    return opts, None


def file_exists_error(path: Path) -> int:
    eprint(f"Error: File `{path.as_posix()}` already exists.")
    eprint("Help: The item you want to create already exists. Try editing the existing file or create a new one with a different name?")
    eprint()
    return 17


def insufficient_new() -> int:
    eprint("Error: Insufficient command line argument provided to use `--yes` option.")
    eprint("Help: You need to provide `entity` in command line to use non-interactive `new`.")
    eprint()
    return 22


def cmd_new(argv: List[str]) -> int:
    opts, code = parse_new(argv)
    if code is not None:
        return code
    assert opts is not None
    pos = opts["positionals"]
    entity = None; name = None
    for p0 in pos:
        if p0 in ("project", "rule", "test", "util") and entity is None:
            entity = p0
        elif name is None:
            name = p0
    if entity is None and not pos:
        if opts["yes"]:
            print("No sgconfig.yml found. Creating a new ast-grep project...")
            return create_project(None)
        print(new_help(True), end=""); return 0
    if entity is None:
        return insufficient_new()
    if entity == "project":
        print("Creating a new ast-grep project...")
        return create_project(name)
    cp, data, err = find_config(opts["config"])
    if err is not None:
        return err
    assert cp is not None and data is not None
    if opts["yes"] and (not name or (entity in ("rule", "util") and not opts["lang"])):
        return insufficient_new()
    if not name:
        name = "new-rule"
    lang = opts["lang"] or "JavaScript"
    if entity == "rule":
        rdir = config_dirs(cp, data, "ruleDirs", "rules")[0]
        tdir = config_dirs(cp, data, "testConfigs", "rule-tests")[0]
        rdir.mkdir(parents=True, exist_ok=True); tdir.mkdir(parents=True, exist_ok=True)
        rpath = rdir / f"{name}.yml"; tpath = tdir / f"{name}-test.yml"
        if rpath.exists(): return file_exists_error(rpath)
        if tpath.exists(): return file_exists_error(tpath)
        rpath.write_text(
            "# yaml-language-server: $schema=https://raw.githubusercontent.com/ast-grep/ast-grep/main/schemas/rule.json\n\n"
            f"id: {name}\nmessage: Add your rule message here....\nseverity: error # error, warning, info, hint\n"
            f"language: {lang}\nrule:\n  pattern: Your Rule Pattern here...\n"
            "# utils: Extract repeated rule as local utility here.\n# note: Add detailed explanation for the rule.",
            encoding="utf-8",
        )
        tpath.write_text(f"id: {name}\nvalid:\n- \"valid code\"\ninvalid:\n- \"invalid code\"\n", encoding="utf-8")
        print(f"Created rules at {rpath.as_posix()}")
        print(f"Created test at {tpath.as_posix()}")
        return 0
    if entity == "test":
        tdir = config_dirs(cp, data, "testConfigs", "rule-tests")[0]
        tdir.mkdir(parents=True, exist_ok=True)
        tpath = tdir / f"{name}-test.yml"
        if tpath.exists(): return file_exists_error(tpath)
        tpath.write_text(f"id: {name}\nvalid:\n- \"valid code\"\ninvalid:\n- \"invalid code\"\n", encoding="utf-8")
        print(f"Created test at {tpath.as_posix()}")
        return 0
    if entity == "util":
        udir = config_dirs(cp, data, "utilDirs", "utils")[0]
        udir.mkdir(parents=True, exist_ok=True)
        upath = udir / f"{name}.yml"
        if upath.exists(): return file_exists_error(upath)
        upath.write_text(f"id: {name}\nlanguage: {lang}\nrule:\n  pattern: Your Rule Pattern here...\n# utils: Extract repeated rule as local utility here.", encoding="utf-8")
        print(f"Created util at {upath.as_posix()}")
        return 0
    return 0


def cmd_lsp(argv: List[str]) -> int:
    config = None
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ("-h", "--help"):
            print(lsp_help(), end=""); return 0
        if a in ("-c", "--config") or a.startswith("--config="):
            v, i, err = opt_value(argv, i, "--config" if a.startswith("--") else a)
            if err: return die(err)
            config = v; continue
        i += 1
    cp, data, err = find_config(config)
    if err is not None:
        return err
    # Minimal JSON-RPC loop: consume stdin to EOF, emit nothing.
    try:
        sys.stdin.read()
    except Exception:
        pass
    return 0


def cmd_completions(argv: List[str]) -> int:
    shell = None
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ("-h", "--help"):
            print(completions_help(), end=""); return 0
        if a in ("-c", "--config") or a.startswith("--config="):
            _, i, _ = opt_value(argv, i, "--config" if a.startswith("--") else a); continue
        if a.startswith("-"):
            return die(f"error: unexpected argument '{a}'\n\nFor more information, try '--help'.")
        shell = a; i += 1
    if shell is None:
        env = os.environ.get("SHELL", "")
        shell = os.path.basename(env) if env else None
    if shell not in ("bash", "zsh", "fish", "powershell", "elvish"):
        eprint("Error: Can not infer which shell to generate completions.")
        eprint("Help: Either specify shell flavor by `sg completions [SHELL]` or set correct `SHELL` environment.")
        eprint("See also: https://ast-grep.github.io/reference/cli.html")
        return 10
    p = prog()
    if shell == "bash":
        print(f"_{p}() {{")
        print("    local i cur prev opts cmd")
        print("    COMPREPLY=()")
        print("    opts=\"run scan test new lsp completions help -h --help -V --version -c --config\"")
        print("}\n")
        print(f"complete -F _{p} -o bashdefault -o default {p}")
    elif shell == "zsh":
        print(f"#compdef {p}\n")
        print(f"_{p}() { alas=0; }".replace(" alas=0; ", ""))
        print(f"compdef _{p} {p}")
    elif shell == "fish":
        print(f"# fish completion for {p}")
        for c in ("run", "scan", "test", "new", "lsp", "completions"):
            print(f"complete -c {p} -f -a \"{c}\"")
    elif shell == "powershell":
        print("using namespace System.Management.Automation")
        print(f"Register-ArgumentCompleter -Native -CommandName '{p}' -ScriptBlock {{ param($wordToComplete, $commandAst, $cursorPosition) }}")
    else:
        print("use builtin;")
        print("use str;")
        print(f"set edit:completion:arg-completer[{p}] = {{|@words| }}")
    return 0


# ---------------------------------------------------------------------------
# top-level dispatcher


def main(argv: List[str]) -> int:
    if not argv:
        eprint(top_help(True),)
        return 2
    # Global flags before command.
    if argv[0] in ("-V", "--version"):
        print(VERSION); return 0
    if argv[0] in ("-h", "--help"):
        print(top_help(argv[0] == "-h"), end=""); return 0
    if argv[0] == "help":
        if len(argv) == 1:
            print(top_help(False), end=""); return 0
        sub = argv[1]
        if sub == "run": print(run_help(False), end=""); return 0
        if sub == "scan": print(scan_help(False), end=""); return 0
        if sub == "test": print(test_help(False), end=""); return 0
        if sub == "new": print(new_help(False), end=""); return 0
        if sub == "lsp": print(lsp_help(), end=""); return 0
        if sub == "completions": print(completions_help(), end=""); return 0
    # Pull leading global config through to the subcommand.
    leading: List[str] = []
    rest = list(argv)
    while rest and (rest[0] in ("-c", "--config") or rest[0].startswith("--config=")):
        if rest[0].startswith("--config="):
            leading.append(rest.pop(0))
        else:
            if len(rest) >= 2:
                leading.extend([rest.pop(0), rest.pop(0)])
            else:
                return die("error: a value is required for '--config <CONFIG_FILE>'")
    if not rest:
        eprint(top_help(True), end="")
        return 2
    cmd = rest[0]
    known = {"run", "scan", "test", "new", "lsp", "completions"}
    if cmd in known:
        args = leading + rest[1:]
        if cmd == "run": return cmd_run(args)
        if cmd == "scan": return cmd_scan(args)
        if cmd == "test": return cmd_test(args)
        if cmd == "new": return cmd_new(args)
        if cmd == "lsp": return cmd_lsp(args)
        if cmd == "completions": return cmd_completions(args)
    # Default command is run when run-specific flags are present.
    if any(a in ("-p", "--pattern", "--stdin") or a.startswith("--pattern=") for a in argv):
        return cmd_run(leading + rest)
    eprint(f"error: unrecognized subcommand '{cmd}'")
    eprint()
    eprint(f"Usage: {prog()} [OPTIONS] <COMMAND>")
    eprint()
    eprint("For more information, try '--help'.")
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
