def load_scan_rules(opts: Dict[str, Any], config_path: Optional[Path], config_data: Optional[Dict[str, Any]]) -> Tuple[Optional[List[Rule]], Optional[int]]:
    rules: List[Rule] = []
    if opts["inline"] is not None:
        try:
            data = parse_yaml_text(opts["inline"])
            rules.append(parse_rule_data(data, "INLINE_RULES"))
        except Exception as e:
            eprint("Error: Cannot parse rule INLINE_RULES")
            eprint("Help: The file is not a valid ast-grep rule. Please refer to doc and fix the error.")
            eprint("See also: https://ast-grep.github.io/guide/rule-config.html")
            eprint(); eprint("✖ Caused by"); eprint("╰▻ Fail to parse yaml as RuleConfig"); eprint(f"╰▻ {e}")
            return None, 8
    elif opts["rules"]:
        for r in opts["rules"]:
            try:
                rules.append(load_rule_file(Path(r)))
            except Exception:
                return None, 8
    else:
        assert config_path is not None and config_data is not None
        for d in config_dirs(config_path, config_data, "ruleDirs", "rules"):
            if d.is_dir():
                for p in sorted(list(d.glob("*.yml")) + list(d.glob("*.yaml"))):
                    try:
                        rules.append(load_rule_file(p))
                    except Exception:
                        return None, 8
    if opts["filter"]:
        try:
            rr = re.compile(opts["filter"])
            rules = [r for r in rules if rr.search(r.id)]
        except re.error:
            pass
    # severity overrides/off
    off = opts["off"]
    if "*" in off:
        rules = []
    elif off:
        rules = [r for r in rules if r.id not in off]
    for r in rules:
        ov = opts["severity_overrides"]
        if "*" in ov:
            r.severity = ov["*"]
        if r.id in ov:
            r.severity = ov[r.id]
    return rules, None


def output_scan_rich(matches: List[Match]) -> None:
    for m in matches:
        sev = m.severity or "help"; rid = m.rule_id or "rule"; msg = m.message or ""
        if m.replacement is not None:
            print(m.file)
            print(f"{sev}[{rid}]: {msg}")
            old = m.source.text
            # Render a single-change diff to match the observed rich fix style.
            tmp = apply_replacements(old, [m])
            print(render_diff(old, tmp, m.file).split("\n", 1)[1])
        else:
            sl, sc = line_col(m.source.text, m.start)
            line_s, line_e = line_bounds(m.source.text, sl)
            line = m.source.text[line_s:line_e]
            print(f"{sev}[{rid}]: {msg}")
            print(f"  ┌─ {m.file}:{sl + 1}:{sc + 1}")
            print("  │")
            print(f"{sl + 1} │ {line}")
            caret_len = max(1, min(max(1, m.end - m.start), max(1, len(line) - sc)))
            print("  │ " + " " * sc + "^" * caret_len)
            print()


def cmd_scan(argv: List[str]) -> int:
    opts, code = parse_scan(argv)
    if code is not None:
        return code
    assert opts is not None
    config_path = None; config_data = None
    if not opts["rules"] and opts["inline"] is None:
        config_path, config_data, err = find_config(opts["config"])
        if err is not None:
            return err
    elif opts["config"]:
        # A specified config should still be readable, but single-rule scans can
        # otherwise run standalone.
        cp, cd, err = find_config(opts["config"])
        if err is not None:
            return err
        config_path, config_data = cp, cd
    rules, err_code = load_scan_rules(opts, config_path, config_data)
    if err_code is not None:
        return err_code
    assert rules is not None
    if opts["stdin"]:
        # Use the first rule language, or JavaScript as a pragmatic default.
        lang = next((r.language for r in rules if r.language), "JavaScript")
        sources = [FileSource("STDIN", sys.stdin.read(), lang)]
        skipped = 0
    else:
        # Collect broadly; per-rule language filtering occurs later.
        sources, skipped = collect_files(opts["paths"] or ["."], None, opts["globs"], opts["follow"], opts["include_hidden"])
    matches: List[Match] = []
    for src in sources:
        for rule in rules:
            matches.extend(matches_for_rule(src, rule))
            if opts["max_results"] and len(matches) >= opts["max_results"]:
                matches = matches[: opts["max_results"]]
                break
    matches.sort(key=lambda m: (m.file, m.start, m.rule_id or ""))
    if opts["inspect"] in ("summary", "entity"):
        eprint("sg: summary|project: isProject=true")
        eprint(f"sg: summary|rule: ruleCount={len(rules)}")
        eprint(f"sg: summary|file: scannedFileCount={len(sources)},skippedFileCount={skipped}")
    if opts["update_all"]:
        by_file: Dict[str, List[Match]] = {}
        count = 0
        for m in matches:
            if m.replacement is not None:
                by_file.setdefault(m.file, []).append(m); count += 1
        for file, ms in by_file.items():
            path = Path(file)
            if not path.exists():
                continue
            old = path.read_text(encoding="utf-8", errors="replace")
            new = apply_replacements(old, ms)
            if new != old:
                path.write_text(new, encoding="utf-8")
        eprint(f"Applied {count} changes")
        return 1 if any((m.severity == "error") for m in matches) else 0
    if opts["files_with_matches"]:
        for m in matches:
            print(m.file)
    elif opts["json"]:
        objs = [match_to_json(m, include_rule=True) for m in matches]
        if opts["json"] == "stream":
            for o in objs:
                print(json.dumps(o, ensure_ascii=False, separators=(",", ":")))
        elif opts["json"] == "compact":
            print(json.dumps(objs, ensure_ascii=False, separators=(",", ":")))
        else:
            print(pretty_json_list(objs))
    elif opts["format"] == "github":
        for m in matches:
            sl, _ = line_col(m.source.text, m.start); el, _ = line_col(m.source.text, m.end)
            sev = "error" if m.severity == "error" else "warning"
            print(f"::{sev} file={m.file},line={sl + 1},endLine={el + 1},title={m.rule_id}::{m.message}")
    elif opts["report_style"] in ("short", "medium"):
        for m in matches:
            sl, sc = line_col(m.source.text, m.start)
            print(f"{m.file}:{sl + 1}:{sc + 1}: {m.severity}[{m.rule_id}]: {m.message}")
    else:
        output_scan_rich(matches)
    err_count = sum(1 for m in matches if m.severity == "error")
    if err_count:
        eprint(f"Error: {err_count} error(s) found in code.")
        eprint("Help: Scan succeeded and found error level diagnostics in the codebase.")
        return 1
    return 0


