def load_project_rules(config_path: Path, data: Dict[str, Any], include_off: bool = True) -> Dict[str, Rule]:
    rules: Dict[str, Rule] = {}
    for d in config_dirs(config_path, data, "ruleDirs", "rules"):
        if d.is_dir():
            for p in sorted(list(d.glob("*.yml")) + list(d.glob("*.yaml"))):
                try:
                    r = load_rule_file(p)
                    if include_off or r.severity != "off":
                        rules[r.id] = r
                except Exception:
                    pass
    return rules


def as_list(x: Any) -> List[str]:
    if x is None:
        return []
    if isinstance(x, list):
        out = []
        for item in x:
            if isinstance(item, dict) and "code" in item:
                out.append(str(item["code"]))
            else:
                out.append(str(item))
        return out
    return [str(x)]


def snapshot_for(rule: Rule, code: str, m: Match) -> Dict[str, Any]:
    d: Dict[str, Any] = {}
    if rule.fix is not None:
        d["fixed"] = apply_template(rule.fix, m)
    d["labels"] = [{"source": m.text, "style": "primary", "start": m.start, "end": m.end}]
    return d


def write_snapshot(path: Path, rid: str, snaps: Dict[str, Dict[str, Any]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    lines = [f"id: {rid}", "snapshots:"]
    for code, snap in snaps.items():
        key = code.replace("\n", "\\n")
        lines.append(f"  {key}:")
        if "fixed" in snap:
            lines.append(f"    fixed: {snap['fixed']}")
        lines.append("    labels:")
        for lab in snap.get("labels", []):
            lines.append(f"    - source: {lab.get('source','')}")
            lines.append(f"      style: {lab.get('style','primary')}")
            lines.append(f"      start: {lab.get('start',0)}")
            lines.append(f"      end: {lab.get('end',0)}")
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def cmd_test(argv: List[str]) -> int:
    opts, code = parse_test(argv)
    if code is not None:
        return code
    assert opts is not None
    cp, data, err = find_config(opts["config"])
    if err is not None:
        return err
    assert cp is not None and data is not None
    rules = load_project_rules(cp, data, include_off=opts["include_off"])
    tdirs = [Path(p) for p in opts["test_dirs"]] if opts["test_dirs"] else config_dirs(cp, data, "testConfigs", "rule-tests")
    tests: List[Path] = []
    for d in tdirs:
        if d.is_dir():
            tests.extend(sorted(list(d.glob("*.yml")) + list(d.glob("*.yaml"))))
    if opts["filter"]:
        try:
            rr = re.compile(opts["filter"])
            tests = [t for t in tests if rr.search(t.stem)]
        except re.error:
            pass
    print(f"Running {len(tests)} tests")
    print()
    print("----------- Case Details -----------")
    passed = failed = 0
    for t in tests:
        data_t = parse_yaml_text(t.read_text(encoding="utf-8", errors="replace")) or {}
        rid = str(data_t.get("id") or t.stem.replace("-test", ""))
        rule = rules.get(rid)
        chars = []
        case_fail = False
        if not rule:
            print(f"[Missing] Rule {rid} is not found.")
            case_fail = True; chars.append("M")
        else:
            valids = as_list(data_t.get("valid"))
            invalids = as_list(data_t.get("invalid"))
            lang = rule.language or "JavaScript"
            for code_s in valids:
                src = FileSource("TEST", code_s, lang)
                ms = matches_for_rule(src, rule)
                if ms:
                    print(f"[Noisy] Expect {rid} to report no issue, but some issues found in:\n")
                    print(f"  {code_s}\n")
                    case_fail = True; chars.append("N")
                else:
                    chars.append(".")
            snap_path = t.parent / str(opts["snapshot_dir"]) / f"{rid}-snapshot.yml"
            existing_text = snap_path.read_text(encoding="utf-8", errors="replace") if snap_path.exists() else ""
            new_snaps: Dict[str, Dict[str, Any]] = {}
            for code_s in invalids:
                src = FileSource("TEST", code_s, lang)
                ms = matches_for_rule(src, rule)
                if not ms:
                    print(f"[Missing] Expect rule {rid} to report issues, but none found in:\n")
                    print(f"  {code_s}\n")
                    case_fail = True; chars.append("M"); continue
                snap = snapshot_for(rule, code_s, ms[0])
                new_snaps[code_s] = snap
                if opts["skip"]:
                    chars.append(".")
                elif opts["update"]:
                    chars.append("U")
                elif not snap_path.exists() or code_s not in existing_text:
                    print(f"[Wrong] No {rid} baseline found.")
                    print("Generated Snapshot:")
                    if "fixed" in snap:
                        print(f"  fixed: {snap['fixed']}")
                    print("  labels:")
                    for lab in snap.get("labels", []):
                        print(f"  - source: {lab['source']}")
                        print(f"    style: {lab['style']}")
                        print(f"    start: {lab['start']}")
                        print(f"    end: {lab['end']}")
                    print("For Code:")
                    print(f"  {code_s}\n")
                    case_fail = True; chars.append("W")
                else:
                    chars.append(".")
            if opts["update"] and new_snaps:
                write_snapshot(snap_path, rid, new_snaps)
                print(f"[Updated] Rule {rid}'s snapshot baseline has been updated.\n")
                for code_s in new_snaps:
                    print(f"  {code_s}\n")
        if case_fail:
            failed += 1; print(f"FAIL {rid}  {''.join(chars)}")
        else:
            passed += 1; print(f"PASS {rid}  {''.join(chars)}")
        print()
    if failed:
        eprint(f"Error: test failed. {passed} passed; {failed} failed;")
        if opts["skip"]:
            eprint("Help: You can use ast-grep playground to debug your rules and test cases.")
            eprint("See also: https://ast-grep.github.io/playground.html")
        else:
            eprint("Help: Test failed due to mismatching snapshots. Run with `--update-all` to update all snapshots, or `--interactive` to update selectively.")
            eprint("See also: https://ast-grep.github.io/guide/test-rule.html")
        return 4
    print(f"test result: ok. {passed} passed; 0 failed;")
    return 0


